// Node: "Normalisasi"  (Code node, mode: Run Once for All Items)
// Input : output node "Webhook Order" ({ headers, params, query, body })
// Output: satu item pesanan dengan format seragam + hasil validasi.
// Menerima dua format: payload generik (lihat test/orders) dan payload webhook Shopify (orders/create).

const body = $input.first().json.body || {};

// "150.000" / "150.000,50" (format Indonesia) atau "150000.00" (Shopify) -> angka
const toNum = (v) => {
  if (typeof v === 'number') return v;
  const s = String(v ?? '').trim().replace(/[^\d.,-]/g, '');
  if (!s) return 0;
  if (/^-?\d{1,3}(\.\d{3})+(,\d+)?$/.test(s)) return parseFloat(s.replace(/\./g, '').replace(',', '.'));
  return parseFloat(s.replace(/,/g, '')) || 0;
};

// 0812..., +62 812..., 812... -> 62812...
const normPhone = (v) => {
  let d = String(v ?? '').replace(/\D/g, '');
  if (d.startsWith('0')) d = '62' + d.slice(1);
  else if (d.startsWith('8')) d = '62' + d;
  return d;
};

const normPayment = (v) => {
  const s = String(v ?? '').toLowerCase();
  if (!s) return '';
  if (s.includes('cod') || s.includes('cash on delivery')) return 'cod';
  if (/(transfer|bank|va|virtual)/.test(s)) return 'transfer';
  if (/(ovo|gopay|dana|shopeepay|ewallet|e-wallet|qris|linkaja)/.test(s)) return 'ewallet';
  if (/(card|credit|kartu|stripe|shopify_payments)/.test(s)) return 'card';
  return 'other';
};

const clean = (v) => String(v ?? '').replace(/\s+/g, ' ').trim();

let o;
if (Array.isArray(body.line_items)) {
  // Format webhook Shopify
  const sa = body.shipping_address || {};
  const cu = body.customer || {};
  o = {
    source: 'shopify',
    order_id: clean(body.name || body.id),
    customer_name: clean(sa.name || [cu.first_name, cu.last_name].filter(Boolean).join(' ')),
    email: clean(body.email || body.contact_email || cu.email).toLowerCase(),
    phone: normPhone(body.phone || sa.phone || cu.phone),
    address: clean([sa.address1, sa.address2].filter(Boolean).join(', ')),
    city: clean(sa.city),
    postal_code: clean(sa.zip),
    items: body.line_items.map((li) => ({
      sku: clean(li.sku),
      name: clean(li.title || li.name),
      qty: Number(li.quantity) || 0,
      price: toNum(li.price),
    })),
    payment_method: normPayment((body.payment_gateway_names || [])[0] || body.gateway),
    total: toNum(body.total_price),
    notes: clean(body.note),
    ordered_at: body.created_at || new Date().toISOString(),
  };
} else {
  // Format generik
  const c = body.customer || {};
  const a = body.shipping_address || {};
  o = {
    source: clean(body.source || 'web').toLowerCase(),
    order_id: clean(body.order_id),
    customer_name: clean(c.name),
    email: clean(c.email).toLowerCase(),
    phone: normPhone(c.phone),
    address: clean(a.address),
    city: clean(a.city),
    postal_code: clean(a.postal_code),
    items: (Array.isArray(body.items) ? body.items : []).map((it) => ({
      sku: clean(it.sku),
      name: clean(it.name),
      qty: Number(it.qty) || 0,
      price: toNum(it.price),
    })),
    payment_method: normPayment(body.payment_method),
    total: toNum(body.total),
    notes: clean(body.notes),
    ordered_at: body.ordered_at || new Date().toISOString(),
  };
}

o.item_qty = o.items.reduce((a, i) => a + i.qty, 0);
o.items_subtotal = o.items.reduce((a, i) => a + i.qty * i.price, 0);

// Validasi: hanya yang membuat pesanan tidak bisa diproses sama sekali.
// Kejanggalan lain (alamat pendek, nama aneh, dll) dinilai di node "Skor Risiko".
const errors = [];
if (!o.order_id) errors.push('order_id kosong');
if (!o.customer_name) errors.push('Nama pelanggan kosong');
if (!/^628\d{7,11}$/.test(o.phone)) errors.push('Nomor HP tidak valid');
if (!o.address) errors.push('Alamat kosong');
if (!o.city) errors.push('Kota kosong');
if (!o.items.length) errors.push('Tidak ada item');
if (o.items.some((i) => i.qty <= 0 || i.price < 0 || !i.name)) errors.push('Ada item dengan nama, qty, atau harga tidak valid');
if (!(o.total > 0)) errors.push('Total harus lebih dari 0');
if (o.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(o.email)) errors.push('Format email tidak valid');
if (!o.payment_method) errors.push('Metode pembayaran kosong');

return [{ json: { ...o, valid: errors.length === 0, errors } }];

// Node: "Skor Risiko"  (Code node, mode: Run Once for All Items)
// Input : output node "Cek Riwayat" (exact_dup, near_dup, prior_rejected, prior_ok)
// Output: pesanan + skor risiko, level, alasan, tag klasifikasi, dan apakah perlu AI.
// Semua aturan bersifat pasti (deterministik) supaya keputusan bisa dijelaskan dan diaudit.

const HIGH_VALUE = 5000000;   // pesanan bernilai besar
const COD_LIMIT = 1000000;    // COD di atas ini dianggap berisiko
const BULK_QTY = 10;          // qty per item yang dianggap borongan
const LEVEL_MEDIUM = 30;
const LEVEL_HIGH = 60;
const DISPOSABLE = ['mailinator.com', 'tempmail.com', '10minutemail.com', 'guerrillamail.com', 'yopmail.com', 'trashmail.com'];

const o = $('Normalisasi').first().json;
const h = $input.first().json;
const hist = {
  near_dup: Number(h.near_dup) || 0,
  prior_rejected: Number(h.prior_rejected) || 0,
  prior_ok: Number(h.prior_ok) || 0,
};

const reasons = [];
const add = (poin, teks) => reasons.push({ poin, teks });

if (o.total >= HIGH_VALUE) add(30, 'Nilai pesanan besar');
if (o.payment_method === 'cod' && o.total >= COD_LIMIT) add(25, 'COD bernilai besar');
if (o.items.some((i) => i.qty >= BULK_QTY)) add(15, 'Jumlah per item tidak wajar');
if (o.address.length < 15) add(15, 'Alamat terlalu pendek');
if (!o.email) add(5, 'Tanpa email');
else if (DISPOSABLE.includes(o.email.split('@')[1])) add(15, 'Email sekali pakai');

const nama = o.customer_name.toLowerCase();
if (/\d/.test(nama) || /(.)\1{3,}/.test(nama) || nama.replace(/\s/g, '').length < 3 || /(asdf|qwer|test|tes123|xxx)/.test(nama)) {
  add(15, 'Nama pelanggan mencurigakan');
}

if (o.items_subtotal > 0 && Math.abs(o.total - o.items_subtotal) / o.items_subtotal > 0.3) {
  add(15, 'Total tidak sesuai rincian item');
}

if (hist.near_dup > 0) add(30, 'Pesanan serupa (HP dan total sama) dalam 30 menit');
if (hist.prior_rejected > 0) add(25, 'Pelanggan pernah punya pesanan ditolak');

const jam = Number(new Intl.DateTimeFormat('en-GB', { hour: 'numeric', hourCycle: 'h23', timeZone: 'Asia/Jakarta' })
  .format(new Date(o.ordered_at)));
if (jam >= 0 && jam < 5) add(5, 'Dipesan dini hari');

if (hist.prior_ok > 0) add(-10, 'Pelanggan lama dengan riwayat baik');

const score = Math.max(0, reasons.reduce((a, r) => a + r.poin, 0));
const level = score >= LEVEL_HIGH ? 'HIGH' : score >= LEVEL_MEDIUM ? 'MEDIUM' : 'LOW';

// Klasifikasi pesanan
const tags = [];
if (o.total >= HIGH_VALUE) tags.push('high_value');
if (o.payment_method === 'cod') tags.push('cod');
if (o.items.some((i) => i.qty >= BULK_QTY)) tags.push('bulk');
tags.push(hist.prior_ok > 0 ? 'repeat_customer' : 'new_customer');

return [{
  json: {
    ...o,
    history: hist,
    risk_score: score,
    risk_level: level,
    risk_reasons: reasons.map((r) => `${r.teks} (${r.poin > 0 ? '+' : ''}${r.poin})`),
    tags,
    needs_ai: level !== 'LOW', // AI hanya dipanggil untuk pesanan yang janggal, supaya hemat kuota
  },
}];

// Node: "Request AI"  (Code node, mode: Run Once for All Items)
// Input : output node "Skor Risiko" (cabang needs_ai = true)
// Output: pesanan + ai_request (body untuk Cloudflare Workers AI)
// Data pribadi (nama, HP, email, alamat lengkap) TIDAK dikirim ke AI. Yang dikirim hanya fitur risiko.

const o = $input.first().json;

const features = {
  total: o.total,
  items_subtotal: o.items_subtotal,
  payment_method: o.payment_method,
  item_count: o.items.length,
  item_qty: o.item_qty,
  items: o.items.slice(0, 10).map((i) => ({ name: i.name.slice(0, 60), qty: i.qty, price: i.price })),
  city: o.city,
  address_length: o.address.length,
  has_email: Boolean(o.email),
  customer_history: o.history,
  rule_score: o.risk_score,
  rule_level: o.risk_level,
  rule_reasons: o.risk_reasons,
  notes: o.notes.slice(0, 200),
};

const system = [
  'Kamu analis risiko pesanan untuk toko online di Indonesia.',
  'Nilai apakah pesanan ini aman diproses. Data pribadi pelanggan sengaja tidak dikirim.',
  'Balas HANYA dengan JSON valid tanpa teks lain, dengan format:',
  '{"verdict":"APPROVE|REVIEW|REJECT","confidence":0.0,"reason":"maksimal 2 kalimat bahasa Indonesia","flags":["..."]}',
  'Pedoman: APPROVE jika pola pesanan wajar. REVIEW jika ada kejanggalan yang perlu dicek manusia.',
  'REJECT hanya jika sangat jelas penipuan atau tidak masuk akal.',
  'confidence = seberapa yakin kamu (0 sampai 1). Jangan mengarang fakta di luar data.',
].join('\n');

const ai_request = {
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: 'Data pesanan:\n' + JSON.stringify(features) },
  ],
  max_tokens: 2000, // Gemma 4 "berpikir" dulu (reasoning), jadi butuh ruang token lebih besar
  temperature: 0.1,
};

return [{ json: { ...o, ai_request } }];

// Node: "Parse AI"  (Code node, mode: Run Once for All Items)
// Input : output node "Cloudflare AI" (HTTP Request, Settings > On Error: Continue)
// Output: pesanan + ai_verdict, ai_confidence, ai_reason, ai_flags
// Kalau AI error atau jawabannya tidak bisa dibaca, pesanan diarahkan ke review manusia.

const o = { ...$('Request AI').first().json };
delete o.ai_request;
const r = $input.first().json || {};

const fallback = (alasan) => [{
  json: { ...o, ai_verdict: 'REVIEW', ai_confidence: 0, ai_reason: alasan, ai_flags: ['ai_error'] },
}];

if (r.error || r.success === false) return fallback('AI tidak bisa dihubungi, perlu dicek manual');

// Format jawaban Workers AI berbeda antar model: result.response (string/objek) atau gaya OpenAI (choices)
let raw = r.result?.response ?? r.result?.choices?.[0]?.message?.content ?? r.choices?.[0]?.message?.content;

let d = null;
try {
  if (raw && typeof raw === 'object') d = raw;
  else if (typeof raw === 'string') {
    const m = raw.replace(/```json|```/g, '').match(/\{[\s\S]*\}/);
    if (m) d = JSON.parse(m[0]);
  }
} catch (e) {
  d = null;
}

const verdict = String(d?.verdict || '').toUpperCase();
if (!['APPROVE', 'REVIEW', 'REJECT'].includes(verdict)) return fallback('Jawaban AI tidak valid, perlu dicek manual');

let conf = Number(d.confidence);
if (!Number.isFinite(conf)) conf = 0.5;
conf = Math.min(1, Math.max(0, conf));

return [{
  json: {
    ...o,
    ai_verdict: verdict,
    ai_confidence: Math.round(conf * 100) / 100,
    ai_reason: String(d.reason || '').slice(0, 300),
    ai_flags: Array.isArray(d.flags) ? d.flags.slice(0, 5).map(String) : [],
  },
}];

// Node: "Tentukan Status"  (Code node, mode: Run Once for All Items)
// Input : dari "Skor Risiko" (risiko LOW, tanpa AI) ATAU dari "Parse AI"
// Output: status akhir, parameter untuk query "Simpan Pesanan", dan teks notifikasi Telegram.
//
// Aturan keputusan:
//   LOW                                   -> APPROVED_AUTO (oleh rules)
//   MEDIUM + AI APPROVE + confidence>=0.7 -> APPROVED_AUTO (oleh ai)
//   selain itu (termasuk semua HIGH)      -> PENDING_REVIEW (owner memutuskan)
// Kemungkinan pesanan ganda (near_dup) selalu ke owner, apa pun kata AI.
// AI tidak pernah menolak pesanan sendiri. Rekomendasi REJECT tetap diputuskan manusia.

const MIN_AI_CONFIDENCE = 0.7;
const o = $input.first().json;

let status = 'PENDING_REVIEW';
let decided_by = 'system';
if (o.risk_level === 'LOW') {
  status = 'APPROVED_AUTO';
  decided_by = 'rules';
} else if (o.risk_level === 'MEDIUM' && !(Number(o.history?.near_dup) > 0) && o.ai_verdict === 'APPROVE' && Number(o.ai_confidence) >= MIN_AI_CONFIDENCE) {
  status = 'APPROVED_AUTO';
  decided_by = 'ai';
}

const rp = (n) => 'Rp' + Math.round(Number(n) || 0).toLocaleString('id-ID');

const params = [
  o.order_id,                                   // $1
  o.source,                                     // $2
  o.customer_name,                              // $3
  o.email || '',                                // $4
  o.phone,                                      // $5
  o.address,                                    // $6
  o.city,                                       // $7
  o.postal_code || '',                          // $8
  JSON.stringify(o.items),                      // $9
  o.item_qty,                                   // $10
  o.payment_method,                             // $11
  o.total,                                      // $12
  o.risk_score,                                 // $13
  o.risk_level,                                 // $14
  JSON.stringify(o.risk_reasons || []),         // $15
  JSON.stringify(o.tags || []),                 // $16
  o.ai_verdict || '',                           // $17
  o.ai_confidence == null ? '' : String(o.ai_confidence), // $18
  o.ai_reason || '',                            // $19
  status,                                       // $20
  decided_by,                                   // $21
];

const telegram_text = [
  'Pesanan perlu review',
  `${o.order_id} (${o.source})`,
  `Pelanggan: ${o.customer_name}, ${o.city}`,
  `Total: ${rp(o.total)} (${o.payment_method})`,
  `Item: ${o.items.map((i) => `${i.qty}x ${i.name}`).join(', ').slice(0, 200)}`,
  '',
  `Skor risiko: ${o.risk_score} (${o.risk_level})`,
  ...(o.risk_reasons || []).map((r) => `- ${r}`),
  '',
  o.ai_verdict ? `Rekomendasi AI: ${o.ai_verdict} (${o.ai_confidence})` : 'Rekomendasi AI: -',
  o.ai_reason || '',
].join('\n').trim();

return [{
  json: {
    ...o,
    status,
    decided_by,
    params,
    telegram_text,
    // Balasan ke pengirim (toko / website demo): hasil analisis tanpa data pribadi
    webhook_response: {
      ok: true,
      order_id: o.order_id,
      status,
      decided_by,
      risk_score: o.risk_score,
      risk_level: o.risk_level,
      risk_reasons: o.risk_reasons || [],
      tags: o.tags || [],
      ai_verdict: o.ai_verdict || null,
      ai_confidence: o.ai_confidence ?? null,
      ai_reason: o.ai_reason || null,
    },
  },
}];
